   /// <summary>
   /// designed from AVA
   /// </summary>
   /// <param name="sender">sender</param>
   /// <param name="e">e</param>
   [SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
       FormDataSourceEventHandler(formDataSourceStr(SalesTable, AVASpecialDiscSalesOrder), FormDataSourceEventType::Writing)]
   public static void AVASpecialDiscSalesOrder_OnWriting(FormDataSource sender, FormDataSourceEventArgs e)
   {
       FormDataSource                      specDiscSalesOrder_dS = sender;
       AVASpecialDiscSalesOrder            specialDiscSalesOrder  = specDiscSalesOrder_dS.cursor();
       FormRun                             formRun = sender.formRun();
       FormDataSource                      salesTable_ds = formRun.dataSource('SalesTable');
       SalesTable                          salesTable = salesTable_ds.cursor();

       if (specialDiscSalesOrder.RecId == 0)
       {
           specialDiscSalesOrder.SalesId = salesTable.SalesId;
           specialDiscSalesOrder.initFromSalesParameters();
       }

   }

