    FormDataSourceEventHandler(formDataSourceStr(SalesTable, AVASpecialDiscSalesOrder), FormDataSourceEventType::Activated)]
public static void AVASpecialDiscSalesOrder_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormDataSource              specDiscSalesOrder_ds = sender;
    AVASpecialDiscSalesOrder    specDiscSalesOrder = specDiscSalesOrder_ds.cursor();

    specDiscSalesOrder_ds.object(fieldNum(AVASpecialDiscSalesOrder,SpecialDiscountPct4)).enabled(specDiscSalesOrder.SpecialDiscountId4 != '');
    specDiscSalesOrder_ds.object(fieldNum(AVASpecialDiscSalesOrder,SpecialDiscountPct5)).enabled(specDiscSalesOrder.SpecialDiscountId5 != '');
    specDiscSalesOrder_ds.object(fieldNum(AVASpecialDiscSalesOrder,SpecialDiscountPct6)).enabled(specDiscSalesOrder.SpecialDiscountId6 != '');
}

