public static void AVASpecialDiscSalesLine_OnWritten(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormRun                 formRun = sender.formRun();
    FormDataSource          salesLine_DS = formRun.dataSource('SalesLine');
    salesLine_DS.reread();
    salesLine_DS.refresh();
}

